import{_ as o,l as i,o as t,c as l,v as d,p as E,x as r,d as n,i as p,S as A,b as e}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"财报期策略","description":"","frontmatter":{"title":"财报期策略","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/earnings-season-strategies.md","filePath":"quant/earnings-season-strategies.md","lastUpdated":1789023840000}'),h={name:"quant/earnings-season-strategies.md"};function u(B,a,m,f,c,P){const s=i("Mermaid");return t(),l("div",null,[a[1]||(a[1]=d('<h1 id="财报期策略" tabindex="-1">财报期策略 <a class="header-anchor" href="#财报期策略" aria-label="Permalink to &quot;财报期策略&quot;">​</a></h1><div class="epigraph"><p>盈余公告把信息塞进一个狭窄窗口：漂移、公告溢价与交易量冲击叠在同一张日历上，却不是同一个可交易对象。</p><footer>—— 漂移见 Bernard and Thomas；公告溢价与成交见 Frazzini and Lamont, Journal of Financial Economics, 2007 前后文献</footer></div><p><a href="/quant/seasonality-anomalies">上一课</a>的时钟是市场日历。财报期的缺口是<strong>公司事件在季报季挤成一簇</strong>：预告、公告、电话会、指引。主干 <a href="/quant/pead-sue">PEAD</a>、<a href="/quant/event-study">事件研究</a> 已写识别与时间戳。<a href="/quant/event-driven-overview">事件驱动全景</a> 把 PEAD 标成漂移桶。本课给策略地图：公告前、公告瞬间、公告后如何分仓，避免把三种 P&amp;L 收成一个「财报因子」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ball–Brown 以来，未预期盈余（SUE）后的漂移被反复测量。Bernard–Thomas 指出市场对序列相关的盈余反应不足。另一条线是公告日本身的溢价与成交：即使 SUE 接近零，暴露在公告上也可能有平均收益，并伴随冲击成本。问题是三套风险：(1) 公告前借券与信息泄漏边界；(2) 公告瞬间买卖价差与缺口；(3) 公告后 PEAD 的换手与衰减。回测若用公告日收盘价当成交，高估与事件研究课是同一错误。</p><p>与季节性：财报季与日历月相关，但不等于「四月效应」。应用公司自己的公告日对齐，而不是用月度虚拟变量。</p><h3 id="不要在公告前假装有公开边缘" tabindex="-1">不要在公告前假装有公开边缘 <a class="header-anchor" href="#不要在公告前假装有公开边缘" aria-label="Permalink to &quot;不要在公告前假装有公开边缘&quot;">​</a></h3><p>公开策略从公告时间戳之后开始。预告与分析师修订可以做成事件，但仍是公开信息。把未公开的仓位数据或窃听当「财报策略」不在本课范围。</p><p><span class="marginnote">拥挤的 PEAD 会把漂移前移到公告后第一小时。信号若仍用日频 SUE 隔日开盘买，吃到的是残渣加冲击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分桶：公告前波动事件（仅公开日历）、公告日流动性供给、SUE/PEAD 截面、指引修正。每桶单独冲击模型。组合：单名跳跃限额；季报周的总 Gamma 与借券。对照：行业中性后的 PEAD 是否还在。容量按可借与公告日深度，不按全市场股票数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公告把私人信息压缩释放。定价可以在方向上对、在速度上慢（漂移），也可以在风险上要求补偿（公告溢价）。灵活资本与做市商库存决定窗口有多短。财报期把许多名字的时钟对齐，相关升，事件驱动课里「平静期夏普」的警告在这里同样适用。</p>',13)),(t(),E(A,null,{default:r(()=>[p(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cal%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%E5%8E%86%22%5D%20--%3E%20Pre%5B%22%E5%85%AC%E5%91%8A%E5%89%8D%20%E5%85%AC%E5%BC%80%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20Cal%20--%3E%20Day%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%20%E7%BC%BA%E5%8F%A3%E4%B8%8E%E5%86%B2%E5%87%BB%22%5D%0A%20%20Cal%20--%3E%20Post%5B%22SUE%20%E6%BC%82%E7%A7%BB%20PEAD%22%5D%0A%20%20Day%20--%3E%20Liq%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BE%9B%E7%BB%99%22%5D%0A%20%20Post%20--%3E%20Xs%5B%22%E6%88%AA%E9%9D%A2%E5%8F%AF%E7%B3%BB%E7%BB%9F%E5%8C%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[n("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"内幕与重大非公开信息是法律边界。电话会语言学、另类数据若用，必须可复现与合规。不要把分析师「偷偷提前」的故事写进回测。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[n("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"财报策略按公告前、公告日、公告后分桶，不是一个因子。"),e("li",null,"时间戳与冲击决定 PEAD 是否还在。"),e("li",null,"季报周相关升高，分散被高估。"),e("li",null,"出处：Bernard and Thomas；Frazzini and Lamont 对公告溢价与成交的讨论；识别见事件研究课。")],-1))])}const b=o(h,[["render",u]]);export{q as __pageData,b as default};
